package com.backend.nutri_predic.datasetmodelov6.service;
import com.backend.nutri_predic.datasetmodelov6.dto.*; import com.backend.nutri_predic.perfilhabitos.repository.EvaluacionPerfilHabitosRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PreparacionDatasetModeloV6Service {private final EvaluacionPerfilHabitosRepository evaluaciones;private final EstadoPreparacionClienteV6Service estado;public PreparacionDatasetModeloV6Service(EvaluacionPerfilHabitosRepository e,EstadoPreparacionClienteV6Service s){evaluaciones=e;estado=s;}@Transactional(readOnly=true)public PreparacionDatasetModeloV6Response auditar(){var f=evaluaciones.findAllByOrderByIdAsc().stream().map(e->estado.estado(e.getCliente().getId(),e.getFechaCorte())).toList();return new PreparacionDatasetModeloV6Response(f.size(),f.stream().filter(EstadoPreparacionClienteV6Response::aptoParaEntrenamiento).count(),f);}}
